import 'package:flutter/material.dart';
class SectionCard extends StatelessWidget { final String title; final IconData? icon; final List<Widget> children; const SectionCard({super.key, required this.title, this.icon, required this.children}); @override Widget build(BuildContext context) => Card(child: Padding(padding: const EdgeInsets.all(16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Row(children: [if (icon != null) ...[Icon(icon, color: Theme.of(context).colorScheme.primary), const SizedBox(width: 10)], Expanded(child: Text(title, style: const TextStyle(fontSize: 18, fontWeight: FontWeight.bold)))]), const SizedBox(height: 8), ...children]))); }
class InfoRow extends StatelessWidget { final String label, value; const InfoRow({super.key, required this.label, required this.value}); @override Widget build(BuildContext context) => Padding(padding: const EdgeInsets.symmetric(vertical: 7), child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [Expanded(child: Text(label, style: TextStyle(color: Colors.grey.shade700))), Expanded(child: Text(value.isEmpty ? 'Not provided' : value, textAlign: TextAlign.end, style: const TextStyle(fontWeight: FontWeight.w600)))])); }
